import fs from 'node:fs';
import path from 'node:path';

const envFile=process.argv[2]; const outDir=process.argv[3]||'.audit/instacomp-25-card-stress';
if(!envFile) throw new Error('Production env file required.'); fs.mkdirSync(outDir,{recursive:true});
for(const raw of fs.readFileSync(envFile,'utf8').split(/\r?\n/)){
  const line=raw.trim(); if(!line||line.startsWith('#')) continue; const m=line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/); if(!m) continue;
  let v=m[2].trim(); if(v.startsWith('"')&&v.endsWith('"')){try{v=JSON.parse(v)}catch{v=v.slice(1,-1)}} else if(v.startsWith("'")&&v.endsWith("'")) v=v.slice(1,-1); process.env[m[1]]=v;
}
const SITE='https://truelycollectables.com';
const VERCEL=String(process.env.VERCEL_TOKEN||'').trim();
const SB=String(process.env.NEXT_PUBLIC_SUPABASE_URL||'').trim().replace(/\/+$/,'');
const SBKEY=String(process.env.SUPABASE_SERVICE_ROLE_KEY||'').trim();
const EBAY_ID=String(process.env.EBAY_CLIENT_ID||'').trim(); const EBAY_SECRET=String(process.env.EBAY_CLIENT_SECRET||'').trim();
if(!VERCEL||!SB||!SBKEY||!EBAY_ID||!EBAY_SECRET) throw new Error('Required production test credentials are unavailable.');

function compact(s){return String(s??'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,' ').trim()}
function normCard(s){return compact(s).replace(/^card\s*/,'').replace(/^no\s*/,'').replace(/\s/g,'')}
function season(s){const v=String(s??'').replace(/[–—]/g,'-'); const m=v.match(/\b((?:19|20)\d{2})\s*[-/]\s*(\d{2,4})\b/); if(!m)return compact(v); const e=m[2].length===2?`${m[1].slice(0,2)}${m[2]}`:m[2]; return `${m[1]}-${e}`}
function match(a,b){const x=compact(a),y=compact(b); if(!x||!y)return false; if(x===y||x.includes(y)||y.includes(x))return true; const xa=x.split(' ').filter(t=>t.length>1),ya=y.split(' ').filter(t=>t.length>1); const hit=xa.filter(t=>ya.includes(t)).length; return hit/Math.max(1,Math.min(xa.length,ya.length))>=.75}
function serialFromText(s){const t=String(s??''); const e=[...t.matchAll(/(?:^|\D)(\d{1,4})\s*\/\s*(\d{1,4})(?:\D|$)/g)].map(m=>({exact:`${Number(m[1])}/${Number(m[2])}`,num:Number(m[1]),run:Number(m[2])})).find(x=>x.num<=x.run&&x.run>=2&&x.run<=9999); if(e)return e; const r=t.match(/(?:numbered|serial(?:ized)?|#'?d)[^0-9]{0,12}(?:\/|to|of)\s*(\d{1,4})\b/i); return r?{exact:null,num:null,run:Number(r[1])}:null}
function complexity(t){t=String(t||'').toLowerCase(); let n=0; if(/auto|autograph|signed/.test(t))n+=4; if(/patch|relic|jersey|memorabilia|swatch|rpa/.test(t))n+=4; if(serialFromText(t))n+=4; if(/prizm|refractor|parallel|silver|gold|red|blue|green|orange|purple|wave|ice|velocity|shimmer|scope|mojo|cracked|sparkle|x-fractor/.test(t))n+=2; if(/\brc\b|rookie/.test(t))n++; return n}
async function jfetch(url,init={},label='request',timeout=45000){const r=await fetch(url,{...init,signal:AbortSignal.timeout(timeout)}); const tx=await r.text(); let j; try{j=tx?JSON.parse(tx):null}catch{j={raw:tx.slice(0,1000)}} if(!r.ok)throw new Error(`${label} HTTP ${r.status}: ${JSON.stringify(j).slice(0,1000)}`); return j}
async function runMacPass(){return jfetch(`${SITE}/api/release/instacomp-deal-hunter-learning-self-test?pass=2`,{method:'POST',headers:{Authorization:`Bearer ${VERCEL}`,Accept:'application/json'}},'production Deal Hunter pass',325000)}
async function recentCandidates(since){const q=new URL(`${SB}/rest/v1/tcos_deal_hunter_candidates`); q.searchParams.set('select','run_id,candidate_key,lane,listing_item_id,listing_url,title,identity,source_payload,evaluation,updated_at'); q.searchParams.set('updated_at',`gte.${since}`); q.searchParams.set('order','updated_at.desc'); q.searchParams.set('limit','200'); return jfetch(q.toString(),{headers:{apikey:SBKEY,Authorization:`Bearer ${SBKEY}`,Accept:'application/json'}},'Supabase candidates')}
async function ebayToken(){const body=new URLSearchParams({grant_type:'client_credentials',scope:'https://api.ebay.com/oauth/api_scope'}); const r=await fetch('https://api.ebay.com/identity/v1/oauth2/token',{method:'POST',headers:{Authorization:`Basic ${Buffer.from(`${EBAY_ID}:${EBAY_SECRET}`).toString('base64')}`,'Content-Type':'application/x-www-form-urlencoded'},body,signal:AbortSignal.timeout(30000)}); const j=await r.json(); if(!r.ok||!j.access_token)throw new Error(`eBay OAuth failed ${JSON.stringify(j).slice(0,500)}`); return j.access_token}
function amap(item){const m=new Map(); for(const a of item?.localizedAspects||[]){const k=compact(a?.name); if(k&&!m.has(k))m.set(k,String(a?.value||'').trim())}return m}
function asp(m,names){for(const n of names){const v=m.get(compact(n)); if(v)return v}return null}
async function ebayItem(token,id){const h={Authorization:`Bearer ${token}`,'X-EBAY-C-MARKETPLACE-ID':'EBAY_US',Accept:'application/json'}; const urls=String(id||'').startsWith('v1|')?[`https://api.ebay.com/buy/browse/v1/item/${encodeURIComponent(id)}`]:[`https://api.ebay.com/buy/browse/v1/item/get_item_by_legacy_id?legacy_item_id=${encodeURIComponent(id)}`,`https://api.ebay.com/buy/browse/v1/item/${encodeURIComponent(`v1|${id}|0`)}`]; for(const u of urls){const r=await fetch(u,{headers:h,signal:AbortSignal.timeout(30000)}); if(r.ok)return r.json()} return null}
function sportFor(row){const l=String(row.lane||''); if(l==='wnba')return'basketball'; if(l==='baseball_prospects')return'baseball'; if(l.includes('demidov')||l.includes('michkov'))return'hockey'; return null}
function expectedFrom(item,row){const m=amap(item), title=String(item?.title||row.title||''); const features=[asp(m,['Features']),asp(m,['Card Attributes']),title].filter(Boolean).join(' | '); const aut=asp(m,['Autographed']); const e={sport:asp(m,['Sport'])||sportFor(row),player:asp(m,['Player/Athlete','Player']),year:asp(m,['Year Manufactured','Season']),manufacturer:asp(m,['Manufacturer','Brand']),setName:asp(m,['Set']),cardNumber:asp(m,['Card Number']),parallel:asp(m,['Parallel/Variety']),rookie:null,autograph:null,memorabilia:null,memorabiliaType:null,serial:serialFromText(title)}; if(aut)e.autograph=/yes|true/i.test(aut); else if(/auto|autograph|signed/i.test(title))e.autograph=true; if(/\brookie\b|\brc\b/i.test(features))e.rookie=true; else if(asp(m,['Features']))e.rookie=false; if(/patch|relic|jersey|memorabilia|swatch|rpa/i.test(features)){e.memorabilia=true;e.memorabiliaType=(features.match(/\b(rpa|patch|jersey|relic|memorabilia|swatch)\b/i)||[])[1]||null} return {title,expected:e}}
function grade(e,ai,title){const c=[]; const add=(f,x,a,p)=>{if(x!==null&&x!==undefined&&String(x)!=='')c.push({field:f,expected:x,actual:a??null,pass:Boolean(p)})}; add('sport',e.sport,ai?.sport,match(e.sport,ai?.sport)); add('player',e.player,ai?.player,match(e.player,ai?.player)); add('year',e.year,ai?.year,season(e.year)===season(ai?.year)||match(e.year,ai?.year)); add('manufacturer',e.manufacturer,ai?.brand,match(e.manufacturer,ai?.brand)); add('setName',e.setName,ai?.setName,match(e.setName,ai?.setName)); add('cardNumber',e.cardNumber,ai?.cardNumber,normCard(e.cardNumber)===normCard(ai?.cardNumber)); add('parallel',e.parallel,ai?.parallel,match(e.parallel,ai?.parallel)); if(e.rookie!==null)add('rookie',e.rookie,ai?.isRookie,Boolean(ai?.isRookie)===e.rookie); if(e.autograph!==null)add('autograph',e.autograph,ai?.isAuto,Boolean(ai?.isAuto)===e.autograph); if(e.memorabilia!==null)add('memorabilia',e.memorabilia,ai?.isRelic,Boolean(ai?.isRelic)===e.memorabilia); if(e.serial?.exact)add('serialExact',e.serial.exact,ai?.serialNumber,compact(e.serial.exact)===compact(ai?.serialNumber)); else if(e.serial?.run)add('serialRun',e.serial.run,ai?.serialNumber,compact(ai?.serialNumber).endsWith(String(e.serial.run))); if(ai?.isAuto===true&&e.autograph!==true&&!/auto|autograph|signed/i.test(title))c.push({field:'unsupportedAutoClaim',expected:false,actual:true,pass:false}); if(ai?.isRelic===true&&e.memorabilia!==true&&!/patch|relic|jersey|memorabilia|swatch|rpa/i.test(title))c.push({field:'unsupportedMemorabiliaClaim',expected:false,actual:true,pass:false}); const passed=c.filter(x=>x.pass).length; return{pass:c.length>0&&passed===c.length,passed,total:c.length,checks:c}}

const startedAt=new Date().toISOString(); let rows=[]; const runReceipts=[];
for(let pass=1;pass<=4;pass++){
  const receipt=await runMacPass(); runReceipts.push({pass,success:receipt?.success===true,run:receipt?.run||null,error:receipt?.error||null});
  rows=await recentCandidates(startedAt);
  const unique=new Map(rows.filter(r=>Array.isArray(r?.source_payload?.imageUrls)&&new Set(r.source_payload.imageUrls).size>=2&&r.identity&&r.listing_item_id).map(r=>[String(r.listing_item_id),r]));
  const sports=new Set([...unique.values()].map(sportFor).filter(Boolean));
  if(unique.size>=35&&sports.size>=3) break;
}
rows=[...new Map(rows.filter(r=>Array.isArray(r?.source_payload?.imageUrls)&&new Set(r.source_payload.imageUrls).size>=2&&r.identity&&r.listing_item_id).map(r=>[String(r.listing_item_id),r])).values()];
const token=await ebayToken(); const enriched=[];
for(const r of rows.sort((a,b)=>complexity(b.title)-complexity(a.title))){const item=await ebayItem(token,r.listing_item_id); if(!item)continue; const {title,expected}=expectedFrom(item,r); if([expected.player,expected.year,expected.setName,expected.cardNumber].filter(Boolean).length<4)continue; enriched.push({...r,sport:sportFor(r),title,expected,listingUrl:item.itemWebUrl||r.listing_url,imageUrls:[...new Set(r.source_payload.imageUrls)],complexity:complexity(title)})}
const selected=[]; const quotas={basketball:8,baseball:8,hockey:9}; for(const [s,n] of Object.entries(quotas)){selected.push(...enriched.filter(x=>x.sport===s).sort((a,b)=>b.complexity-a.complexity).slice(0,n))} if(selected.length<25){const used=new Set(selected.map(x=>String(x.listing_item_id))); for(const x of enriched.sort((a,b)=>b.complexity-a.complexity)){if(selected.length>=25)break;if(!used.has(String(x.listing_item_id))){selected.push(x);used.add(String(x.listing_item_id))}}}
if(selected.length<25)throw new Error(`Only ${selected.length} independently-grounded two-image evaluated listings were available after ${runReceipts.length} real Deal Hunter passes.`);
const results=selected.slice(0,25).map((r,i)=>{const g=grade(r.expected,r.identity,r.title); return{index:i+1,sport:r.sport,lane:r.lane,title:r.title,listingItemId:r.listing_item_id,listingUrl:r.listingUrl,imageUrls:r.imageUrls.slice(0,2),expected:r.expected,ai:r.identity,complexity:r.complexity,grade:g,evaluation:r.evaluation,runId:r.run_id}});
for(const r of results)console.log(`${String(r.index).padStart(2,'0')}/25 ${r.grade.pass?'PASS':'FAIL'} ${r.sport} ${r.title.slice(0,110)}`);
const total=results.reduce((n,r)=>n+r.grade.total,0), passed=results.reduce((n,r)=>n+r.grade.passed,0), cards=results.filter(r=>r.grade.pass).length;
const summary={schema:'truelycollectables.instacomp.25-card-stress.v2',completedAt:new Date().toISOString(),runReceipts,selectedListings:25,sports:Object.fromEntries(['basketball','baseball','hockey'].map(s=>[s,results.filter(r=>r.sport===s).length])),complexCounts:{autograph:results.filter(r=>r.expected.autograph===true).length,memorabilia:results.filter(r=>r.expected.memorabilia===true).length,serialized:results.filter(r=>r.expected.serial?.run).length,parallel:results.filter(r=>r.expected.parallel).length,rookie:results.filter(r=>r.expected.rookie===true).length},cardsPassed:cards,cardsFailed:25-cards,cardAccuracyPercent:Number((cards/25*100).toFixed(1)),fieldChecksPassed:passed,fieldChecksTotal:total,fieldAccuracyPercent:total?Number((passed/total*100).toFixed(1)):0,perfect:cards===25,failures:results.filter(r=>!r.grade.pass).map(r=>({index:r.index,title:r.title,listingUrl:r.listingUrl,failedChecks:r.grade.checks.filter(x=>!x.pass)}))};
fs.writeFileSync(path.join(outDir,'summary.json'),JSON.stringify(summary,null,2)); fs.writeFileSync(path.join(outDir,'results.json'),JSON.stringify(results,null,2)); console.log(JSON.stringify(summary,null,2));
